import { Component } from '@angular/core';
import { MisCompras } from 'src/app/models/mis-compras';
import { UsuarioService } from 'src/app/services/usuario.service';
import { MisComprasService } from 'src/app/services/mis-compras.service';

@Component({
  selector: 'app-mis-compras',
  templateUrl: './mis-compras.component.html',
  styleUrls: ['./mis-compras.component.css']
})
export class MisComprasComponent {

  public totalCompras: number = 0; //varible donde almacenaremos el total
  public misCompras: MisCompras[] = [];
  public emailUsuario: string = "null";

  //------------------------------------



  //ATRIBUTOS ejercicio 31---
  public nombreProducto: string="";
  public precioProducto: number = 0;
  //---fin del ejercicio 31---




  constructor(public misComprasService: MisComprasService,
    public usuarioService: UsuarioService){}

  ngOnInit(): void {
    this.emailUsuario = this.usuarioService.obtenerEmailUsuarioLogeado(); //obtienes el usuario logado

    this.misComprasService.misComprasSeleccionadas$.subscribe( //recorres las compras del usuario logado
      compras => {
        this.misCompras = compras;
        //calculas el totoal de la comrpa
        this.totalCompras = 0;

        for (let compra of compras) {
          this.totalCompras += Number(compra.total);
        }
        console.log("MIS COMPRAS: ", compras);
      },
      error => console.error('Error al obtener compras', error)
    );
  }

  //metodo calcularTotal
  calcularTotalCompras(): void {
    this.totalCompras = 0; //contador
    this.misCompras.forEach(compra => {
      this.totalCompras += Number(compra.total);
    });
  }



}
<div id="misCompras" style="display:none">


<!--EJERCICIO 31-->
<div *ngIf="productoMasCaro && precioMasCaro" class="alert alert-info mt-4">
  <strong>Producto más caro:</strong> {{ productoMasCaro }}<br>
  <strong>Precio:</strong> {{ precioMasCaro.toFixed(2) }} €
</div>
<!--FIN DEL EJERCICIO 31-->

    <h5>Total de todas las compras: {{ totalCompras.toFixed(2) }} €</h5>

   <!-- MongooseJS.com   -- API -- MODELS -->
    <div class="container mt-4" style="margin-bottom:3em" *ngFor="let compra of misCompras">

        <div class="card">
            <div class="card-header">
                <h5 class="card-title">Nº Pedido: {{compra.numPedido}} <span style="color:darkgray; font-style: italic; font-weight: lighter;">{{compra.fecha | date:'dd/MM/yyyy'}}</span></h5>
            </div>
            <div class="card-body">
                <table class="table">
                    <thead>
                        <tr>
                            <th>ID Compra</th>
                            <th>Productos</th>
                            <th>Cantidad</th>
                            <th>Total</th>
                        </tr>
                    </thead>
                    <tbody *ngFor="let producto of compra.productos">
                        <tr>
                            <td>{{producto.idCompra}}</td>
                            <td>{{producto.nombreProd}}</td>
                            <td>{{producto.cantidad}}</td>
                            <td>{{producto.totalProd}} €</td>

                        </tr>
                    </tbody>
                </table>
                <div class="text-right">
                    <p style="text-align:right; font-weight: bold">Total Pedido: {{compra.total}} €</p>
                </div>
            </div>
        </div>
    </div>
</div>
